pub fn parse_n<I>(args: I) -> i32
where
    I: IntoIterator,
    I::Item: AsRef<str>,
{
    let mut args = args.into_iter();
    let _program = args.next();

    match args.next() {
        Some(value) => atoi_i32(value.as_ref()),
        None => 10,
    }
}

fn atoi_i32(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut sign = 1i64;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                sign = -1;
                index += 1;
            }
            _ => {}
        }
    }

    let first_digit = index;
    let mut value = 0i64;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        value = value
            .saturating_mul(10)
            .saturating_add(i64::from(bytes[index] - b'0'));
        index += 1;
    }

    if index == first_digit {
        return 0;
    }

    value
        .saturating_mul(sign)
        .clamp(i64::from(i32::MIN), i64::from(i32::MAX)) as i32
}

#[cfg(test)]
mod tests {
    use super::{atoi_i32, parse_n};

    #[test]
    fn matches_atoi_style_parsing() {
        assert_eq!(atoi_i32("abc"), 0);
        assert_eq!(atoi_i32("+2x"), 2);
        assert_eq!(atoi_i32(" 2"), 2);
        assert_eq!(atoi_i32("-1"), -1);
    }

    #[test]
    fn uses_same_default_as_cpp() {
        let args = vec!["test10".to_string()];
        assert_eq!(parse_n(args), 10);
    }
}

