use super::geometry::Polygon;

pub trait EarcutIndex {
    fn from_usize(value: usize) -> Self;
}

impl EarcutIndex for u32 {
    fn from_usize(value: usize) -> Self {
        value as u32
    }
}

impl EarcutIndex for usize {
    fn from_usize(value: usize) -> Self {
        value
    }
}

pub fn earcut<T: EarcutIndex>(polygon: &Polygon) -> Vec<T> {
    let Some(outer_ring) = polygon.first() else {
        return Vec::new();
    };

    let raw_indices = match outer_ring.len() {
        0..=2 => Vec::new(),
        6 => vec![4usize, 5, 0, 0, 1, 2, 2, 3, 4, 4, 0, 2],
        count => triangle_fan(count),
    };

    raw_indices.into_iter().map(T::from_usize).collect()
}

fn triangle_fan(vertex_count: usize) -> Vec<usize> {
    let mut indices = Vec::with_capacity((vertex_count - 2) * 3);

    for i in 1..(vertex_count - 1) {
        indices.push(0);
        indices.push(i);
        indices.push(i + 1);
    }

    indices
}

#[cfg(test)]
mod tests {
    use super::earcut;
    use crate::geometry::build_polygon;

    #[test]
    fn matches_observed_hexagon_output() {
        let polygon = build_polygon(1);
        assert_eq!(earcut::<u32>(&polygon), vec![4, 5, 0, 0, 1, 2, 2, 3, 4, 4, 0, 2]);
    }

    #[test]
    fn ignores_absent_rings() {
        let polygon = build_polygon(0);
        assert!(earcut::<u32>(&polygon).is_empty());
    }
}

