use std::fmt::Display;
use std::io::{self, Write};

pub fn write_indices<T: Display>(indices: &[T]) {
    let mut stdout = io::stdout().lock();

    for index in indices {
        write!(stdout, "{} ", index).expect("failed to write program output");
    }
}

