use std::f64::consts::PI;

pub type Point = [f64; 2];
pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn build_polygon(n: i32) -> Polygon {
    let mut polygon = Vec::new();

    for layer in 0..n {
        let vertex_count = usize::try_from((layer + 3) * 2).unwrap_or(0);
        let mut ring = Vec::with_capacity(vertex_count);
        let radius = f64::from(layer + 1) * 0.3;
        let offset = f64::from(layer) * 0.1;
        let scale = radius + offset;

        for i in 0..vertex_count {
            let angle = 2.0 * PI * (i as f64) / (vertex_count as f64);
            ring.push([scale * angle.cos(), scale * angle.sin()]);
        }

        polygon.push(ring);
    }

    polygon
}
